using System;using System.Drawing;using System.Globalization;using System.Linq;using System.Windows.Forms;
namespace BeamScheduleFormatter {
partial class ProgramOfWorksForm {
 FlowLayoutPanel doorSettings;NumericUpDown jambDepthDefault,jambThicknessDefault;
 void AddDoorSettings(FlowLayoutPanel actions){doorSettings=new FlowLayoutPanel{Visible=false,Padding=new Padding(16),AutoScroll=true};Controls.Add(doorSettings);jambDepthDefault=DoorNumber("Unassigned jamb depth (mm)",50,500,150);jambThicknessDefault=DoorNumber("Jamb thickness (mm)",10,100,50);doorSettings.Controls.Add(new Label{Text="Jamb depth follows the thickest assigned wall. Unassigned door/window schedules use the depth above. Jamb thickness is a project default; 50mm retains the existing app allowance. Wooden leaf thickness is fixed at 45mm. Confirm jamb sizes against the approved detail.",Width=760,Height=100});Button(actions,"Door / Window Settings",()=>SettingsWorkspace.Show(this,"Wooden doors & windows",new[]{"Jamb & leaf"},new Control[]{doorSettings}));}
 NumericUpDown DoorNumber(string title,decimal min,decimal max,decimal value){var group=new FlowLayoutPanel{Width=350,Height=80,FlowDirection=FlowDirection.TopDown};group.Controls.Add(new Label{Text=title,Width=335,Height=28});var number=new NumericUpDown{Minimum=min,Maximum=max,Value=value,DecimalPlaces=0,Width=300};number.ValueChanged+=(s,e)=>{if(!filling)Recalculate();};group.Controls.Add(number);doorSettings.Controls.Add(group);return number;}
 void AutomaticWoodDimensions(DataGridViewRow row){double depth=jambDepthDefault==null?150:(double)jambDepthDefault.Value;var assigned=openingAssignments.Where(x=>string.Equals(x.Schedule,Cell(row,0),StringComparison.OrdinalIgnoreCase)).Select(x=>x.Wall).ToArray();if(assigned.Length==0&&Cell(row,2)!="")assigned=new[]{Cell(row,2)};var thicknesses=MasonryGrids().SelectMany(g=>g.Rows.Cast<DataGridViewRow>()).Where(r=>!r.IsNewRow&&assigned.Contains(Cell(r,0),StringComparer.OrdinalIgnoreCase)).Select(r=>Cell(r,18)=="100"?100.0:150.0).ToArray();if(thicknesses.Length>0)depth=thicknesses.Max();row.Cells[7].Value=(depth/1000).ToString("0.###",CultureInfo.InvariantCulture);row.Cells[8].Value=((jambThicknessDefault==null?50:(double)jambThicknessDefault.Value)/1000).ToString("0.###",CultureInfo.InvariantCulture);row.Cells[9].Value="45";foreach(int column in new[]{7,8,9}){row.Cells[column].ReadOnly=true;row.Cells[column].Style.BackColor=Color.FromArgb(239,244,248);}}
 void WriteDoorSettings(System.Xml.XmlElement root){root.SetAttribute("jambDepthDefault",jambDepthDefault.Value.ToString(CultureInfo.InvariantCulture));root.SetAttribute("jambThicknessDefault",jambThicknessDefault.Value.ToString(CultureInfo.InvariantCulture));}
 void ReadDoorSettings(System.Xml.XmlElement root){jambDepthDefault.Value=root.HasAttribute("jambDepthDefault")?decimal.Parse(root.GetAttribute("jambDepthDefault"),CultureInfo.InvariantCulture):150;jambThicknessDefault.Value=root.HasAttribute("jambThicknessDefault")?decimal.Parse(root.GetAttribute("jambThicknessDefault"),CultureInfo.InvariantCulture):50;}
}
}
